/**
 *
 * TreeSelection exposes selection state and callbacks via render-prop,
 * letting users compose their own selection UI (checkbox, radio, switch, ...).
 * Automatically detects header vs node context: rendered inside `Tree.Header`
 * it yields aggregate fields (`isAllSelected`, `toggleAll`); inside a `Tree.Node`
 * it yields per-row fields (`isSelected`, `toggle`).
 *
 * [Live Demo](https://www.primereact.org/tree/)
 *
 * @module TreeSelection
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Defines passthrough(pt) options type in TreeSelection component.
 */
export type TreeSelectionPassThroughType<E> = PassThroughType<TreeSelectionInstance, E>;
/**
 * Defines passthrough(pt) options of TreeSelection component.
 */
export interface TreeSelectionPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeSelectionPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TreeSelection component.
 */
export interface TreeSelectionProps extends BaseComponentProps<TreeSelectionInstance, unknown, TreeSelectionPassThrough> {
    /**
     * Override the toggle mode used inside the render-prop.
     * - 'radio': select only one node, no deselect on re-click.
     * - 'checkbox': tri-state with cascade propagation.
     * - 'single': select one node, deselect on re-click.
     *
     * When omitted, defaults to `'single'` for `selectionMode="single"`,
     * `'checkbox'` for `selectionMode="checkbox"`, otherwise `'checkbox'`.
     */
    mode?: 'radio' | 'checkbox' | 'single';
}
/**
 * Defines valid state in TreeSelection component.
 */
export interface TreeSelectionState {
}
/**
 * Defines the methods and properties exposed by TreeSelection component.
 * Rendered once per node and once per header slot; inspect `isHeader` to pick the right fields.
 */
export interface TreeSelectionExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
    /**
     * True when rendered inside `Tree.Header` (aggregate / select-all context).
     */
    isHeader: boolean;
    /**
     * True when **all** visible nodes are selected. Meaningful only in header context.
     */
    isAllSelected: boolean;
    /**
     * True when **some** visible nodes (but not all) are selected. Meaningful only in header context.
     */
    isSomeSelected: boolean;
    /**
     * Select or deselect every visible node. Meaningful only in header context.
     */
    toggleAll: (event: React.SyntheticEvent) => void;
    /**
     * True when the current node is selected. Meaningful only in node context.
     */
    isSelected: boolean;
    /**
     * True when the current node is partially selected (checkbox cascade tri-state).
     * Meaningful only in node context.
     */
    isPartiallySelected: boolean;
    /**
     * Toggle selection for the current node. Meaningful only in node context.
     */
    toggle: (event: React.SyntheticEvent) => void;
}
/**
 * Instance of TreeSelection component.
 */
export type TreeSelectionInstance = ComponentInstance<TreeSelectionProps, TreeSelectionState, TreeSelectionExposes>;
